window.TEACH_SLIDES['7-17'] = [{"k": "title", "html": "<p class=\"ts-kicker\">ថ្នាក់ទី ៧ · មេរៀនទី ១៧</p><h1>រង្វង់</h1><div class=\"ts-obj\"><h3>គោលបំណង</h3><ol class=\"ts-bullets\"><li>បង្ហាញសញ្ញាណរង្វង់និងធាតុសំខាន់ៗនៃរង្វង់</li><li>កំណត់បរិមាត្ររង្វង់និងផ្ទៃក្រឡាថាស</li><li>កំណត់ប្រវែងធ្នូនៃរង្វង់និងរកផ្ទៃក្រឡាចម្រៀកថាស ។</li></ol></div>", "c": "cover"}, {"k": "title", "html": "<h1>1. សញ្ញាណរង្វង់</h1>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">1. សញ្ញាណរង្វង់</p><h2>ឧទាហរណ៍</h2><p class=\"ts-exh\">ឧទាហរណ៍ 1</p><p>រូបកាក់ រូបស្លាកសញ្ញាចរាចរណ៍ មុខនាឡិកា \\(\\dots\\) ផ្តល់នូវសញ្ញាណរង្វង់ ។</p><p class=\"ts-exh\">ឧទាហរណ៍ 2</p><p>គេមានចំណុចនឹង \\(O\\) មួយ គេដៅចំណុចឱ្យបានយ៉ាងតិច 20 ដែលឋិតនៅចម្ងាយ \\(2~\\text{cm}\\) ពីចំណុច \\(O\\) រួចភ្ជាប់ចំណុចទាំងនោះ ។</p><p>គេសង្កេតឃើញថា គ្រប់ចំណុចដែលឋិតនៅចម្ងាយ \\(2~\\text{cm}\\) ពីចំណុច \\(O\\) ឋិតនៅលើខ្សែកោងបិទជិតហៅថា រង្វង់ ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">1. សញ្ញាណរង្វង់</p><h2>ជាទូទៅ</h2><p>រង្វង់ គឺជាខ្សែកោងបិទជិតដែលគ្រប់ចំណុចនៃខ្សែកោង ឋិតនៅចម្ងាយស្មើគ្នាពីចំណុចនឹងមួយហៅថា <b>ផ្ចិតរង្វង់</b> ។</p><p>រង្វង់នេះមានផ្ចិត \\(O\\) កាំ \\(OC\\) អង្កត់ផ្ចិត \\(AB\\) អង្កត់ធ្នូនិងធ្នូ \\(BC\\) ។</p>"}, {"k": "title", "html": "<h1>2. បរិមាត្ររង្វង់</h1>"}, {"k": "", "html": "<p class=\"ts-kicker\"></p><h2>2. បរិមាត្ររង្វង់</h2><p>ប្រវែងជុំវិញរង្វង់ហៅថា <b>បរិមាត្ររង្វង់</b> ។</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">2. បរិមាត្ររង្វង់</p><h2>ឧទាហរណ៍</h2><p>គេយកកង 5 មានអង្កត់ផ្ចិតខុសៗគ្នាគិតជា \\(\\text{cm}\\) មកបង្វិលដោយមិនរអិលនៅលើម៉ែត្រឈើមួយ រួចគេវាស់អង្កត់ផ្ចិតនិងបរិមាត្ររង្វង់នៃថាសនីមួយៗ គេបានលទ្ធផលដូចតទៅ ៖</p><table class=\"ts-table\"><tr><td>រង្វង់</td><td>\\(a\\)</td><td>\\(b\\)</td><td>\\(c\\)</td><td>\\(d\\)</td><td>\\(e\\)</td></tr><tr><td>អង្កត់ផ្ចិត \\(d =\\)</td><td>4</td><td>6</td><td>8</td><td>10</td><td>12</td></tr><tr><td>បរិមាត្រ \\(p =\\)</td><td>12.5</td><td>19</td><td>25.1</td><td>31.4</td><td>37.8</td></tr><tr><td>\\(p \\div d =\\)</td><td>3.12</td><td>3.16</td><td>3.13</td><td>3.14</td><td>3.15</td></tr></table><p>គេឃើញថា ផលធៀបប្រវែងបរិមាត្រនិងអង្កត់ផ្ចិតមានតម្លៃប្រហាក់ប្រហែលគ្នា ។ គេតាងតម្លៃប្រហែលនេះដោយ “\\(\\pi\\)” អានថា “ពី” ស្មើនឹង \\(3.1416\\dots\\) ។ គេបាន \\(\\frac{p}{d} = \\pi\\), \\(p = \\pi d\\) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">2. បរិមាត្ររង្វង់</p><h2>ជាទូទៅ</h2><p>រង្វង់មានកាំ \\(R\\) ឬអង្កត់ផ្ចិត \\(d = 2R\\) មានបរិមាត្រ \\[p = 2\\pi R \\quad \\left(\\pi \\approx 3.1416 \\approx 3.14 \\text{ ឬ } \\pi \\approx \\frac{22}{7}\\right) \\text{ ។}\\]</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">2. បរិមាត្ររង្វង់</p><h2>ឧទាហរណ៍</h2><p class=\"ts-exh\">ឧទាហរណ៍ 1</p><p>គណនាបរិមាត្ររង្វង់មានកាំស្មើនឹង \\(14~\\text{cm}\\) ដោយយក \\(\\pi \\approx \\frac{22}{7}\\) ។</p><p>បរិមាត្ររង្វង់ ៖ \\[\\begin{aligned}\np &amp;= 2\\pi R \\\\\n&amp;= 2 \\times \\frac{22}{7} \\times 14 \\\\\n&amp;= 88~\\text{cm} \\text{ ។}\n\\end{aligned}\\]</p><p class=\"ts-exh\">ឧទាហរណ៍ 2</p><p>គណនាកាំរង្វង់ដោយស្គាល់បរិមាត្រ \\(p = 219.8~\\text{cm}\\) និងយក \\(\\pi \\approx 3.14\\) ។</p><p>ដោយបរិមាត្ររង្វង់ \\(p = 2\\pi R\\) គេបាន ៖ \\[\\begin{aligned}\nR &amp;= \\frac{p}{2\\pi} \\\\\n&amp;= \\frac{219.8}{2 \\times 3.14} \\\\\n&amp;= 35~\\text{cm} \\text{ ។}\n\\end{aligned}\\]</p><p class=\"ts-exh\">ឧទាហរណ៍ 3</p><p>គណនាអង្កត់ផ្ចិតនៃរង្វង់ដោយស្គាល់បរិមាត្រ \\(p = 25~\\text{cm}\\) និងយក \\(\\pi \\approx 3.14\\) ។</p><p>ដោយបរិមាត្ររង្វង់ \\(p = \\pi d\\) នោះ ៖ \\[\\begin{aligned}\nd &amp;= \\frac{p}{\\pi} \\\\\n&amp;= \\frac{25}{3.14} \\\\\n&amp;\\approx 7.96~\\text{cm} \\text{ ។}\n\\end{aligned}\\]</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2. បរិមាត្ររង្វង់</p><h2>លំហាត់គំរូ 1</h2><p>កង់យោងបង្វិលទី 1 ត្រូវបានស្ថាបនាអំពីដែកក្នុងឆ្នាំ 1893 នៅឯកន្លែងតាំងពិព័រណ៍ពិភពលោកក្នុងក្រុងស៊ីកាហ្គោ ។ វាមានកាំប្រវែង \\(125~\\text{feet}\\) ឬ \\(38.1~\\text{m}\\) ទម្ងន់ \\(1200~\\text{តោន}\\) ហើយអាចផ្ទុកមនុស្សបាន \\(2100~\\text{នាក់}\\) ។ បើគេចំណាយ \\(50~\\text{សេន}\\) ក្នុងម្នាក់ គេអាចឡើងជិះកង់យោងបង្វិលបានរយៈពេល \\(20~\\text{នាទី}\\) ។</p><p>តើអ្នកជិះកង់យោងបង្វិលបានប្រវែងប៉ុន្មានក្នុងមួយជុំ ?</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2. បរិមាត្ររង្វង់</p><h2>ដំណោះស្រាយ</h2><p>\\[\\begin{aligned}\np &amp;= 2\\pi R \\\\\n&amp;\\approx 2 \\times 3.14 \\times 125~\\text{feet} \\\\\n&amp;= 785~\\text{feet}\n\\end{aligned}\\] ដូច្នេះ អ្នកជិះធ្វើដំណើរបានប្រវែង \\(785~\\text{feet}\\) ក្នុង 1 ជុំ ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">2. បរិមាត្ររង្វង់</p><h2>សម្គាល់</h2><p>\\(1~\\text{feet} = 30.48~\\text{cm}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2. បរិមាត្ររង្វង់</p><h2>ប្រតិបត្តិ</h2><p>គណនាបរិមាត្រនៃរូបខាងក្រោមនេះ ដោយយក \\(\\pi \\approx \\frac{22}{7}\\) ៖</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>ចម្រៀកកង្ហារពីរផ្គុំគ្នាមានកាំ \\(5~\\text{cm}\\) ។</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>រូបរាងកីឡដ្ឋាន មានបណ្តោយចតុកោណកែង \\(1.10~\\text{m}\\) និងទទឹង \\(80~\\text{cm}\\) អមដោយកន្លះរង្វង់សងខាង ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2. បរិមាត្ររង្វង់</p><h2>ចម្លើយ</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គេបាន ៖ \\[\\begin{aligned}\np &amp;= 2 \\times \\left(\\frac{1}{4} \\times 2\\pi R\\right) + 4R \\\\\n&amp;= \\pi R + 4R \\\\\n&amp;= \\frac{22}{7} \\times 5 + 4 \\times 5 \\\\\n&amp;= \\frac{110}{7} + 20 \\\\\n&amp;= \\frac{250}{7}~\\text{cm} \\text{ ។}\n\\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>គេបាន ៖ \\[\\begin{aligned}\np &amp;= 2 \\times 1.10 + \\pi d \\\\\n&amp;= 2.20 + \\frac{22}{7} \\times 0.8 \\\\\n&amp;= \\frac{15.4}{7} + \\frac{17.6}{7} \\\\\n&amp;= \\frac{33}{7}~\\text{m} \\text{ ។}\n\\end{aligned}\\]</div></li></ul>"}, {"k": "title", "html": "<h1>3. ផ្ទៃក្រឡាថាស</h1>"}, {"k": "", "html": "<p class=\"ts-kicker\"></p><h2>3. ផ្ទៃក្រឡាថាស</h2><p>គេគូសរង្វង់កាំ \\(R\\) នៅលើក្រដាសកាតុង ហើយកាត់ថាសឱ្យបានជា 16 ចំណែកស្មើគ្នា រួចផ្គុំចំណែកទាំងនោះឱ្យមានរាងជាចតុកោណកែង ។ ចតុកោណកែងនេះមានវិមាត្រ \\(\\pi R\\) និង \\(R\\) ។</p><p>ដូច្នេះ ផ្ទៃក្រឡាថាស = ផ្ទៃក្រឡាចតុកោណកែង ឬ \\(\\mathcal{A} = \\pi R \\times R = \\pi R^2\\) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">3. ផ្ទៃក្រឡាថាស</p><h2>រូបមន្ត</h2><p>ផ្ទៃក្រឡាថាសមានកាំ \\(R\\) កំណត់ដោយ \\[\\mathcal{A} = \\pi R^2 \\text{ ។}\\]</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">3. ផ្ទៃក្រឡាថាស</p><h2>ឧទាហរណ៍</h2><p class=\"ts-exh\">ឧទាហរណ៍ 1</p><p>គណនាផ្ទៃក្រឡាថាសមានកាំ \\(10~\\text{cm}\\) ដោយយក \\(\\pi \\approx 3.141\\) ។</p><p>តាមរូបមន្តផ្ទៃក្រឡាថាសមានកាំ \\(R\\) កំណត់ដោយ ៖ \\[\\begin{aligned}\n\\mathcal{A} &amp;= \\pi R^2 \\\\\n&amp;= 3.141 \\times 10^2 \\\\\n&amp;= 314.1~\\text{cm}^2 \\text{ ។}\n\\end{aligned}\\]</p><p class=\"ts-exh\">ឧទាហរណ៍ 2</p><p>គណនាផ្ទៃក្រឡាថាសមានអង្កត់ផ្ចិត \\(14~\\text{cm}\\) ។ \\(\\left(\\pi \\approx \\frac{22}{7}\\right)\\)</p><p>តាមរូបមន្តផ្ទៃក្រឡាថាសមានអង្កត់ផ្ចិត \\(d\\) ៖ \\[\\begin{aligned}\n\\mathcal{A} &amp;= \\frac{\\pi d^2}{4} \\\\\n&amp;= \\frac{22}{7} \\times \\frac{14^2}{4} \\\\\n&amp;= 154~\\text{cm}^2 \\text{ ។}\n\\end{aligned}\\]</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">3. ផ្ទៃក្រឡាថាស</p><h2>លំហាត់គំរូ 1</h2><p>គណនាបរិមាត្រនិងផ្ទៃក្រឡានៃរូបខាងស្តាំ ។ \\(\\left(\\pi \\approx \\frac{22}{7}\\right)\\)</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">3. ផ្ទៃក្រឡាថាស</p><h2>ដំណោះស្រាយ</h2><p>គេចែករូបនេះជាពីរផ្នែក</p><p>បរិមាត្រផ្នែកទី 1 ៖ \\[p_1 = 20 + 20 + 14 = 54~\\text{cm}\\] បរិមាត្រផ្នែកទី 2 ៖ \\[\\begin{aligned}\np_2 &amp;= \\frac{1}{2}\\pi d \\\\\n&amp;= \\frac{1}{2} \\times \\frac{22}{7} \\times 14 \\\\\n&amp;= 22~\\text{cm} \\text{ ។}\n\\end{aligned}\\] បរិមាត្រនៃរូបគឺ ៖ \\[p = p_1 + p_2 = 54 + 22 = 76~\\text{cm} \\text{ ។}\\]</p><p>ផ្ទៃក្រឡាចតុកោណកែង ៖ \\[\\mathcal{A}_1 = 20 \\times 14 = 280~\\text{cm}^2\\] ផ្ទៃក្រឡាកន្លះថាស ៖ \\[\\begin{aligned}\n\\mathcal{A}_2 &amp;= \\frac{1}{2} \\times \\frac{1}{4} \\times \\frac{22}{7} \\times 14^2 \\\\\n&amp;= 77~\\text{cm}^2 \\text{ ។}\n\\end{aligned}\\] ផ្ទៃក្រឡាសរុបគឺ ៖ \\[\\mathcal{A} = \\mathcal{A}_1 + \\mathcal{A}_2 = 280 + 77 = 357~\\text{cm}^2 \\text{ ។}\\]</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">3. ផ្ទៃក្រឡាថាស</p><h2>លំហាត់គំរូ 2</h2><p>គណនាផ្ទៃក្រឡាផ្នែកពណ៌នៃរូបខាងស្តាំ ។ (\\(\\pi \\approx 3.14\\))</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">3. ផ្ទៃក្រឡាថាស</p><h2>ដំណោះស្រាយ</h2><p>ផ្ទៃក្រឡាថាសធំ ៖ \\[\\begin{aligned}\n\\mathcal{A}_1 &amp;= \\pi R^2 \\\\\n&amp;= \\pi \\times 5^2 \\\\\n&amp;\\approx 3.14 \\times 25 \\\\\n&amp;\\approx 78.5~\\text{cm}^2 \\text{ ។}\n\\end{aligned}\\] ផ្ទៃក្រឡាថាសតូច ៖ \\[\\begin{aligned}\n\\mathcal{A}_2 &amp;= \\pi r^2 \\\\\n&amp;= \\pi \\times 3^2 \\\\\n&amp;\\approx 3.14 \\times 9 \\\\\n&amp;\\approx 28.26~\\text{cm}^2 \\text{ ។}\n\\end{aligned}\\] ផ្ទៃក្រឡាផ្នែកពណ៌ ៖ \\[\\begin{aligned}\n\\mathcal{A} &amp;= \\mathcal{A}_1 - \\mathcal{A}_2 \\\\\n&amp;= 78.5 - 28.26 \\\\\n&amp;\\approx 50.24~\\text{cm}^2 \\text{ ។}\n\\end{aligned}\\]</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">3. ផ្ទៃក្រឡាថាស</p><h2>ប្រតិបត្តិ</h2><p>គណនាផ្ទៃក្រឡាផ្នែកពណ៌នៃរូបខាងស្តាំ ។ \\(\\left(\\pi \\approx \\frac{22}{7}\\right)\\)</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>ការ៉េមានរង្វង់ចារឹកក្នុងកាំ \\(3~\\text{cm}\\) ផ្នែកពណ៌នៅជ្រុងទាំងបួន ។</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>រង្វង់រួមផ្ចិតមានអង្កត់ផ្ចិតក្នុង \\(8~\\text{cm}\\) និងកម្រាស់ \\(4~\\text{cm}\\) ផ្នែកពណ៌ជាក្រវាត់ ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">3. ផ្ទៃក្រឡាថាស</p><h2>ចម្លើយ</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គេបាន ៖ ជ្រុងការ៉េគឺ \\(a = 2 \\times 3 = 6~\\text{cm}\\) ។ \\[\\begin{aligned}\n\\mathcal{A} &amp;= \\mathcal{A}_{\\text{ការ៉េ}} - \\mathcal{A}_{\\text{ថាស}} \\\\\n&amp;= 6^2 - \\frac{22}{7} \\times 3^2 \\\\\n&amp;= 36 - \\frac{198}{7} \\\\\n&amp;= \\frac{252 - 198}{7} \\\\\n&amp;= \\frac{54}{7}~\\text{cm}^2 \\text{ ។}\n\\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>គេបាន ៖ កាំរង្វង់តូច \\(r = \\frac{8}{2} = 4~\\text{cm}\\) ។ កាំរង្វង់ធំ \\(R = 4 + 4 = 8~\\text{cm}\\) ។ \\[\\begin{aligned}\n\\mathcal{A} &amp;= \\pi(R^2 - r^2) \\\\\n&amp;= \\frac{22}{7}(8^2 - 4^2) \\\\\n&amp;= \\frac{22}{7}(64 - 16) \\\\\n&amp;= \\frac{22}{7} \\times 48 \\\\\n&amp;= \\frac{1056}{7}~\\text{cm}^2 \\text{ ។}\n\\end{aligned}\\]</div></li></ul>"}, {"k": "title", "html": "<h1>4. ផ្ទៃក្រឡាចម្រៀកថាស</h1>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">4. ផ្ទៃក្រឡាចម្រៀកថាស</p><h2>ឧទាហរណ៍</h2><p>បើគេកាត់ថាសមួយចំណែកនៃថាសទាំងមូល ចំណែកថាសនេះហៅថា <b>ចម្រៀកថាស</b> ។</p>"}, {"k": "", "html": "<p class=\"ts-kicker\">4. ផ្ទៃក្រឡាចម្រៀកថាស · 4.1. និយមន័យ</p><h2>4.1. និយមន័យ</h2><p>ចម្រៀកថាស គឺជាផ្នែកមួយនៃថាសដែលខណ្ឌដោយកាំពីរ ។ មុំផ្គុំឡើងដោយកាំទាំងពីរនៃរង្វង់ហៅថា <b>មុំផ្ចិតនៃចម្រៀកថាស</b> ។</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">4. ផ្ទៃក្រឡាចម្រៀកថាស · 4.2. ប្រវែងធ្នូនៃរង្វង់</p><h2>ឧទាហរណ៍</h2><p>គណនាប្រវែងធ្នូ \\(\\arc{AB}\\) នៃរង្វង់មានកាំរង្វាស់ \\(5~\\text{cm}\\) ត្រូវនឹងមុំផ្ចិត \\(45^\\circ\\) ។</p><p>មុំ \\(360^\\circ\\) ត្រូវនឹងប្រវែងធ្នូនៃបរិមាត្ររង្វង់ \\(2\\pi R\\) មុំ \\(1^\\circ\\) ត្រូវនឹងប្រវែងធ្នូនៃរង្វង់ \\(\\frac{2\\pi R}{360^\\circ}\\) មុំ \\(45^\\circ\\) ត្រូវនឹងប្រវែងធ្នូនៃរង្វង់ ៖ \\[\\arc{AB} = \\frac{2\\pi R}{360^\\circ} \\times 45^\\circ = \\frac{2\\pi \\times 5}{360^\\circ} \\times 45^\\circ = \\frac{5\\pi}{4}~\\text{cm}\\] ដូច្នេះ ប្រវែងធ្នូ \\(\\arc{AB} = \\frac{5\\pi}{4}~\\text{cm}\\) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">4. ផ្ទៃក្រឡាចម្រៀកថាស · 4.2. ប្រវែងធ្នូនៃរង្វង់</p><h2>ជាទូទៅ</h2><p>ប្រវែងធ្នូ \\(\\arc{AB}\\) នៃរង្វង់កាំ \\(R\\) និងមុំផ្ចិត \\(\\alpha^\\circ\\) កំណត់ដោយ \\[\\arc{AB} = 2\\pi R \\times \\frac{\\alpha^\\circ}{360^\\circ} \\text{ ។}\\]</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">4. ផ្ទៃក្រឡាចម្រៀកថាស · 4.2. ប្រវែងធ្នូនៃរង្វង់</p><h2>លំហាត់គំរូ 1</h2><p>គណនាប្រវែងធ្នូ \\(\\arc{AB}\\) នៃរង្វង់ មានកាំរង្វាស់ \\(5~\\text{cm}\\) ត្រូវនឹងមុំផ្ចិត \\(30^\\circ\\) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">4. ផ្ទៃក្រឡាចម្រៀកថាស · 4.2. ប្រវែងធ្នូនៃរង្វង់</p><h2>ដំណោះស្រាយ</h2><p>គេបាន ៖ \\[\\begin{aligned}\n\\arc{AB} &amp;= 2\\pi R \\times \\frac{30^\\circ}{360^\\circ} \\\\\n&amp;= 2\\pi \\times 5 \\times \\frac{30}{360} \\\\\n&amp;= \\frac{5\\pi}{6}~\\text{cm}\n\\end{aligned}\\] ដូច្នេះ ប្រវែងធ្នូ \\(\\arc{AB} = \\frac{5\\pi}{6}~\\text{cm}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">4. ផ្ទៃក្រឡាចម្រៀកថាស · 4.2. ប្រវែងធ្នូនៃរង្វង់</p><h2>លំហាត់គំរូ 2</h2><p>គណនាបរិមាត្រនៃចម្រៀកថាសមានកាំស្មើនឹង \\(12~\\text{cm}\\) និងមុំផ្ចិតនៃចម្រៀកថាសមានរង្វាស់ \\(144^\\circ\\) ។ (\\(\\pi \\approx 3.14\\))</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">4. ផ្ទៃក្រឡាចម្រៀកថាស · 4.2. ប្រវែងធ្នូនៃរង្វង់</p><h2>ដំណោះស្រាយ</h2><p>ប្រវែងធ្នូ \\(\\arc{AB}\\) នៃរង្វង់ត្រូវនឹងមុំផ្ចិត \\(144^\\circ\\) កំណត់ដោយ ៖ \\[\\begin{aligned}\n\\arc{AB} &amp;= 2 \\times 3.14 \\times 12~\\text{cm} \\times \\frac{144^\\circ}{360^\\circ} \\\\\n&amp;= 30.14~\\text{cm}\n\\end{aligned}\\] បរិមាត្រនៃចម្រៀកថាស ៖ \\[\\begin{aligned}\np &amp;= 30.14~\\text{cm} + 12~\\text{cm} + 12~\\text{cm} \\\\\n&amp;= 54.14~\\text{cm} \\text{ ។}\n\\end{aligned}\\]</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">4. ផ្ទៃក្រឡាចម្រៀកថាស · 4.3. ផ្ទៃក្រឡាចម្រៀកថាស</p><h2>ឧទាហរណ៍</h2><p>គណនាផ្ទៃក្រឡាចម្រៀកថាសមានកាំប្រវែង \\(12~\\text{cm}\\) មុំផ្ចិតនៃចម្រៀកថាស \\(45^\\circ\\) ។</p><p>មុំ \\(360^\\circ\\) ត្រូវនឹងផ្ទៃក្រឡាថាស \\(\\pi R^2\\) មុំ \\(1^\\circ\\) ត្រូវនឹងផ្ទៃក្រឡាចម្រៀកថាស \\(\\frac{\\pi R^2}{360^\\circ}\\) មុំ \\(45^\\circ\\) ត្រូវនឹងផ្ទៃក្រឡាចម្រៀកថាស ៖ \\[\\begin{aligned}\n\\mathcal{A} &amp;= \\frac{\\pi R^2}{360^\\circ} \\times 45^\\circ \\\\\n&amp;= \\frac{\\pi \\times 12^2}{360^\\circ} \\times 45^\\circ \\\\\n&amp;= 18\\pi~\\text{cm}^2 \\text{ ។}\n\\end{aligned}\\]</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">4. ផ្ទៃក្រឡាចម្រៀកថាស · 4.3. ផ្ទៃក្រឡាចម្រៀកថាស</p><h2>ជាទូទៅ</h2><p>ផ្ទៃក្រឡាចម្រៀកថាស \\(\\mathcal{A}\\) នៃរង្វង់មានកាំ \\(R\\) និងមុំផ្ចិតនៃចម្រៀកថាស \\(\\alpha^\\circ\\) កំណត់ដោយ \\[\\mathcal{A} = \\pi R^2 \\times \\frac{\\alpha^\\circ}{360^\\circ} \\text{ ។}\\]</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">4. ផ្ទៃក្រឡាចម្រៀកថាស · 4.3. ផ្ទៃក្រឡាចម្រៀកថាស</p><h2>លំហាត់គំរូ 1</h2><p>គណនាផ្ទៃក្រឡាចម្រៀកថាស មានកាំប្រវែង \\(6~\\text{cm}\\) និងមុំផ្ចិតនៃចម្រៀកថាស \\(60^\\circ\\) ។ (\\(\\pi \\approx 3.14\\))</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">4. ផ្ទៃក្រឡាចម្រៀកថាស · 4.3. ផ្ទៃក្រឡាចម្រៀកថាស</p><h2>ដំណោះស្រាយ</h2><p>ផ្ទៃក្រឡាចម្រៀកថាស ៖ \\[\\begin{aligned}\n\\mathcal{A} &amp;= \\pi \\times 6^2 \\times \\frac{60^\\circ}{360^\\circ} \\\\\n&amp;= 6\\pi~\\text{cm}^2 \\\\\n&amp;= 6 \\times 3.14~\\text{cm}^2 \\\\\n&amp;= 18.84~\\text{cm}^2 \\text{ ។}\n\\end{aligned}\\]</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">4. ផ្ទៃក្រឡាចម្រៀកថាស · 4.3. ផ្ទៃក្រឡាចម្រៀកថាស</p><h2>លំហាត់គំរូ 2</h2><p>គណនាផ្ទៃក្រឡានិងបរិមាត្រនៃចម្រៀកថាសមានកាំ \\(12.6~\\text{cm}\\) និងមុំផ្ចិតនៃចម្រៀកថាសមានរង្វាស់ \\(120^\\circ\\) ។ \\(\\left(\\pi \\approx \\frac{22}{7}\\right)\\)</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">4. ផ្ទៃក្រឡាចម្រៀកថាស · 4.3. ផ្ទៃក្រឡាចម្រៀកថាស</p><h2>ដំណោះស្រាយ</h2><p>ផ្ទៃក្រឡាចម្រៀកថាស ៖ ដោយស្គាល់ \\(\\pi \\approx \\frac{22}{7}\\) និងកាំ \\(r = 12.6~\\text{cm}\\) គេបាន \\[\\begin{aligned}\n\\mathcal{A} &amp;= \\frac{120}{360} \\times \\pi r^2 \\\\\n&amp;= \\frac{120}{360} \\times \\frac{22}{7} \\times (12.6)^2~\\text{cm}^2 \\\\\n&amp;= 166.32~\\text{cm}^2 \\text{ ។}\n\\end{aligned}\\] ប្រវែងធ្នូ \\(\\arc{AB}\\) នៃរង្វង់ដែលត្រូវនឹងមុំផ្ចិត \\(120^\\circ\\) ៖ \\[\\begin{aligned}\n\\arc{AB} &amp;= 2 \\times \\frac{22}{7} \\times 12.6~\\text{cm} \\times \\frac{120^\\circ}{360^\\circ} \\\\\n&amp;= 26.4~\\text{cm} \\text{ ។}\n\\end{aligned}\\] បរិមាត្រនៃចម្រៀកថាស ៖ \\[\\begin{aligned}\np &amp;= 26.4~\\text{cm} + 12.6~\\text{cm} + 12.6~\\text{cm} \\\\\n&amp;= 51.6~\\text{cm} \\text{ ។}\n\\end{aligned}\\]</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">4. ផ្ទៃក្រឡាចម្រៀកថាស · 4.3. ផ្ទៃក្រឡាចម្រៀកថាស</p><h2>ប្រតិបត្តិ</h2><p>គណនាផ្ទៃក្រឡាផ្នែកពណ៌នៃរូបខាងក្រោម ។ \\(\\left(\\pi \\approx \\frac{22}{7}\\right)\\)</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">4. ផ្ទៃក្រឡាចម្រៀកថាស · 4.3. ផ្ទៃក្រឡាចម្រៀកថាស</p><h2>ចម្លើយ <span class=\"ts-pg\">(១/២)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គេបាន ៖ \\[\\begin{aligned}\n\\mathcal{A} &amp;= \\pi R^2 \\times \\frac{45^\\circ}{360^\\circ} \\\\\n&amp;= \\frac{22}{7} \\times 4^2 \\times \\frac{1}{8} \\\\\n&amp;= \\frac{44}{7}~\\text{cm}^2 \\text{ ។}\n\\end{aligned}\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ខ.</span><div>គេបាន ៖ \\[\\begin{aligned}\n\\mathcal{A} &amp;= \\pi R^2 \\times \\frac{90^\\circ}{360^\\circ} \\\\\n&amp;= \\frac{22}{7} \\times 2^2 \\times \\frac{1}{4} \\\\\n&amp;= \\frac{22}{7}~\\text{cm}^2 \\text{ ។}\n\\end{aligned}\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">គ.</span><div>គេបាន ៖ \\[\\begin{aligned}\n\\mathcal{A} &amp;= \\frac{1}{2} \\pi R^2 \\\\\n&amp;= \\frac{1}{2} \\times \\frac{22}{7} \\times 8^2 \\\\\n&amp;= \\frac{704}{7}~\\text{cm}^2 \\text{ ។}\n\\end{aligned}\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>គេបាន ៖ \\[\\begin{aligned}\n\\mathcal{A} &amp;= \\pi R^2 \\times \\frac{120^\\circ}{360^\\circ} \\\\\n&amp;= \\frac{22}{7} \\times 9^2 \\times \\frac{1}{3} \\\\\n&amp;= \\frac{594}{7}~\\text{cm}^2 \\text{ ។}\n\\end{aligned}\\]</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">4. ផ្ទៃក្រឡាចម្រៀកថាស · 4.3. ផ្ទៃក្រឡាចម្រៀកថាស</p><h2>ចម្លើយ <span class=\"ts-pg\">(២/២)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ង.</span><div>គេបាន ៖ \\[\\begin{aligned}\n\\mathcal{A} &amp;= \\pi R^2 \\times \\frac{90^\\circ}{360^\\circ} \\\\\n&amp;= \\frac{22}{7} \\times 9^2 \\times \\frac{1}{4} \\\\\n&amp;= \\frac{891}{14}~\\text{cm}^2 \\text{ ។}\n\\end{aligned}\\] (ចំណាំ ៖ តាមរូបសៀវភៅ ផ្នែកពណ៌មានមុំ \\(270^\\circ\\) ប៉ុន្តែចម្លើយពុម្ពសៀវភៅគណនាតាមមុំ \\(90^\\circ\\) គឺ \\(\\mathcal{A} = \\frac{891}{14}\\) ។ បើគណនាតាមមុំ \\(270^\\circ\\) គឺ \\(\\mathcal{A} = \\frac{2673}{14}\\) ។)</div></li></ul>"}, {"k": "title", "html": "<p class=\"ts-kicker\">មេរៀនទី ១៧</p><h1>លំហាត់</h1><p class=\"ts-sub\">រង្វង់</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១</h2><p>រកបរិមាត្ររង្វង់មួយដោយស្គាល់ប្រវែងកាំស្មើនឹង \\(10~\\text{cm}\\) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១</h2><p>រូបមន្តបរិមាត្ររង្វង់ ៖ \\[p = 2\\pi R\\] ដោយកាំ \\(R = 10~\\text{cm}\\) និងយក \\(\\pi \\approx 3.14\\) (ឬ \\(\\pi \\approx \\frac{22}{7}\\)) គេបាន ៖ \\[\\begin{aligned}\n    p &amp;= 2 \\times 3.14 \\times 10 \\\\\n    &amp;= 62.8~\\text{cm}\n    \\end{aligned}\\] (បើគណនាតាម \\(\\pi \\approx \\frac{22}{7}\\) នោះ \\(p = 2 \\times \\frac{22}{7} \\times 10 = \\frac{440}{7} \\approx 62.86~\\text{cm}\\)) ។</p><p>ដូចនេះ បរិមាត្ររង្វង់គឺ \\(p = 62.8~\\text{cm}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ២</h2><p>រកបរិមាត្ររង្វង់មួយដោយស្គាល់ប្រវែងអង្កត់ផ្ចិតស្មើនឹង \\(16~\\text{cm}\\) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ២</h2><p>រូបមន្តបរិមាត្ររង្វង់តាមអង្កត់ផ្ចិត ៖ \\[p = \\pi d\\] ដោយអង្កត់ផ្ចិត \\(d = 16~\\text{cm}\\) និងយក \\(\\pi \\approx 3.14\\) គេបាន ៖ \\[\\begin{aligned}\n    p &amp;= 3.14 \\times 16 \\\\\n    &amp;= 50.24~\\text{cm}\n    \\end{aligned}\\] (បើគណនាតាម \\(\\pi \\approx \\frac{22}{7}\\) នោះ \\(p = \\frac{22}{7} \\times 16 = \\frac{352}{7} \\approx 50.29~\\text{cm}\\)) ។</p><p>ដូចនេះ បរិមាត្ររង្វង់គឺ \\(p = 50.24~\\text{cm}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៣</h2><p>រកកាំរង្វង់មួយដោយស្គាល់បរិមាត្រស្មើនឹង \\(33.91~\\text{cm}\\) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៣</h2><p>តាមរូបមន្តបរិមាត្ររង្វង់ \\(p = 2\\pi R\\) គេទាញបានកាំ ៖ \\[R = \\frac{p}{2\\pi}\\] ដោយ \\(p = 33.91~\\text{cm}\\) និងយក \\(\\pi \\approx 3.14\\) គេបាន ៖ \\[\\begin{aligned}\n    R &amp;= \\frac{33.91}{2 \\times 3.14} \\\\\n    &amp;= \\frac{33.91}{6.28} \\\\\n    &amp;\\approx 5.4~\\text{cm}\n    \\end{aligned}\\] ដូចនេះ កាំរង្វង់គឺ \\(R \\approx 5.4~\\text{cm}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៤</h2><p>រកអង្កត់ផ្ចិតរង្វង់មួយដោយស្គាល់បរិមាត្រស្មើនឹង \\(33.91~\\text{cm}\\) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៤</h2><p>តាមរូបមន្តបរិមាត្ររង្វង់ \\(p = \\pi d\\) គេទាញបានអង្កត់ផ្ចិត ៖ \\[d = \\frac{p}{\\pi}\\] ដោយ \\(p = 33.91~\\text{cm}\\) និងយក \\(\\pi \\approx 3.14\\) គេបាន ៖ \\[\\begin{aligned}\n    d &amp;= \\frac{33.91}{3.14} \\\\\n    &amp;\\approx 10.8~\\text{cm}\n    \\end{aligned}\\] ដូចនេះ អង្កត់ផ្ចិតរង្វង់គឺ \\(d \\approx 10.8~\\text{cm}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៥</h2><p>គណនាបរិមាត្ររង្វង់និងផ្ទៃក្រឡាថាសមានកាំដូចខាងក្រោម ៖</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(7~\\text{cm}\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(28~\\text{cm}\\)</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>\\(16.8~\\text{cm}\\)</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>\\(63~\\text{cm}\\)</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៥ <span class=\"ts-pg\">(១/២)</span></h2><p>រូបមន្តបរិមាត្ររង្វង់ \\(p = 2\\pi R\\) និងផ្ទៃក្រឡាថាស \\(\\mathcal{A} = \\pi R^2\\) ដោយយក \\(\\pi \\approx \\frac{22}{7}\\) ៖</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>ចំពោះ \\(R = 7~\\text{cm}\\) ៖ \\[\\begin{aligned}\n        p &amp;= 2 \\times \\frac{22}{7} \\times 7 = 44~\\text{cm} \\\\\n        \\mathcal{A} &amp;= \\frac{22}{7} \\times 7^2 = 154~\\text{cm}^2\n        \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>ចំពោះ \\(R = 28~\\text{cm}\\) ៖ \\[\\begin{aligned}\n        p &amp;= 2 \\times \\frac{22}{7} \\times 28 = 176~\\text{cm} \\\\\n        \\mathcal{A} &amp;= \\frac{22}{7} \\times 28^2 = 2464~\\text{cm}^2\n        \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>ចំពោះ \\(R = 16.8~\\text{cm}\\) ៖ \\[\\begin{aligned}\n        p &amp;= 2 \\times \\frac{22}{7} \\times 16.8 = 105.6~\\text{cm} \\\\\n        \\mathcal{A} &amp;= \\frac{22}{7} \\times (16.8)^2 = 887.04~\\text{cm}^2\n        \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>ចំពោះ \\(R = 63~\\text{cm}\\) ៖ \\[\\begin{aligned}\n        p &amp;= 2 \\times \\frac{22}{7} \\times 63 = 396~\\text{cm} \\\\\n        \\mathcal{A} &amp;= \\frac{22}{7} \\times 63^2 = 12474~\\text{cm}^2\n        \\end{aligned}\\]</div></li></ul><p>ដូចនេះ លទ្ធផលគណនាគឺ ៖</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៥ <span class=\"ts-pg\">(២/២)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(p = 44~\\text{cm}, \\mathcal{A} = 154~\\text{cm}^2\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(p = 176~\\text{cm}, \\mathcal{A} = 2464~\\text{cm}^2\\)</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>\\(p = 105.6~\\text{cm}, \\mathcal{A} = 887.04~\\text{cm}^2\\)</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>\\(p = 396~\\text{cm}, \\mathcal{A} = 12474~\\text{cm}^2\\) ។</div></li></ul>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៦</h2><p>គណនាបរិមាត្ររង្វង់និងផ្ទៃក្រឡាកន្លះថាសមានកាំដូចខាងក្រោម ៖</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(8.4~\\text{cm}\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(14~\\text{cm}\\)</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>\\(21~\\text{cm}\\)</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>\\(35~\\text{cm}\\)</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៦ <span class=\"ts-pg\">(១/២)</span></h2><p>រូបមន្តបរិមាត្ររង្វង់ \\(p = 2\\pi R\\) និងផ្ទៃក្រឡាកន្លះថាស \\(\\mathcal{A} = \\frac{1}{2}\\pi R^2\\) ដោយយក \\(\\pi \\approx \\frac{22}{7}\\) ៖</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>ចំពោះ \\(R = 8.4~\\text{cm}\\) ៖ \\[\\begin{aligned}\n        p &amp;= 2 \\times \\frac{22}{7} \\times 8.4 = 52.8~\\text{cm} \\\\\n        \\mathcal{A} &amp;= \\frac{1}{2} \\times \\frac{22}{7} \\times (8.4)^2 = 110.88~\\text{cm}^2\n        \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>ចំពោះ \\(R = 14~\\text{cm}\\) ៖ \\[\\begin{aligned}\n        p &amp;= 2 \\times \\frac{22}{7} \\times 14 = 88~\\text{cm} \\\\\n        \\mathcal{A} &amp;= \\frac{1}{2} \\times \\frac{22}{7} \\times 14^2 = 308~\\text{cm}^2\n        \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>ចំពោះ \\(R = 21~\\text{cm}\\) ៖ \\[\\begin{aligned}\n        p &amp;= 2 \\times \\frac{22}{7} \\times 21 = 132~\\text{cm} \\\\\n        \\mathcal{A} &amp;= \\frac{1}{2} \\times \\frac{22}{7} \\times 21^2 = 693~\\text{cm}^2\n        \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>ចំពោះ \\(R = 35~\\text{cm}\\) ៖ \\[\\begin{aligned}\n        p &amp;= 2 \\times \\frac{22}{7} \\times 35 = 220~\\text{cm} \\\\\n        \\mathcal{A} &amp;= \\frac{1}{2} \\times \\frac{22}{7} \\times 35^2 = 1925~\\text{cm}^2\n        \\end{aligned}\\]</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៦ <span class=\"ts-pg\">(២/២)</span></h2><p>(ចំណាំ ៖ បើគិតបរិមាត្រនៃកន្លះថាសបិទជិត \\(p_{\\text{កន្លះ}} = \\pi R + 2R\\) នោះ ៖ ក. \\(43.2~\\text{cm}\\), ខ. \\(72~\\text{cm}\\), គ. \\(108~\\text{cm}\\), ឃ. \\(180~\\text{cm}\\)) ។</p><p>ដូចនេះ ផ្ទៃក្រឡាកន្លះថាសគឺ ៖</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(p = 52.8~\\text{cm}, \\mathcal{A} = 110.88~\\text{cm}^2\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(p = 88~\\text{cm}, \\mathcal{A} = 308~\\text{cm}^2\\)</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>\\(p = 132~\\text{cm}, \\mathcal{A} = 693~\\text{cm}^2\\)</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>\\(p = 220~\\text{cm}, \\mathcal{A} = 1925~\\text{cm}^2\\) ។</div></li></ul>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៧</h2><p>គណនាបរិមាត្រនៃរង្វង់ដោយស្គាល់ផ្ទៃក្រឡាថាសដូចខាងក្រោម ៖</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(2464~\\text{cm}^2\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(3850~\\text{cm}^2\\)</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>\\(5544~\\text{cm}^2\\)</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៧</h2><p>រូបមន្តផ្ទៃក្រឡាថាស \\(\\mathcal{A} = \\pi R^2 \\implies R^2 = \\frac{\\mathcal{A}}{\\pi} = \\mathcal{A} \\times \\frac{7}{22}\\) និងបរិមាត្រ \\(p = 2\\pi R\\) ៖</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>ចំពោះ \\(\\mathcal{A} = 2464~\\text{cm}^2\\) ៖ \\[\\begin{aligned}\n        R^2 &amp;= 2464 \\times \\frac{7}{22} = 784 \\implies R = \\sqrt{784} = 28~\\text{cm} \\\\\n        p &amp;= 2 \\times \\frac{22}{7} \\times 28 = 176~\\text{cm}\n        \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>ចំពោះ \\(\\mathcal{A} = 3850~\\text{cm}^2\\) ៖ \\[\\begin{aligned}\n        R^2 &amp;= 3850 \\times \\frac{7}{22} = 1225 \\implies R = \\sqrt{1225} = 35~\\text{cm} \\\\\n        p &amp;= 2 \\times \\frac{22}{7} \\times 35 = 220~\\text{cm}\n        \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>ចំពោះ \\(\\mathcal{A} = 5544~\\text{cm}^2\\) ៖ \\[\\begin{aligned}\n        R^2 &amp;= 5544 \\times \\frac{7}{22} = 1764 \\implies R = \\sqrt{1764} = 42~\\text{cm} \\\\\n        p &amp;= 2 \\times \\frac{22}{7} \\times 42 = 264~\\text{cm}\n        \\end{aligned}\\]</div></li></ul><p>ដូចនេះ បរិមាត្រនៃរង្វង់គឺ ៖</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(p = 176~\\text{cm}\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(p = 220~\\text{cm}\\)</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>\\(p = 264~\\text{cm}\\) ។</div></li></ul>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៨</h2><p>អង្កត់ផ្ចិតនៃកង់មួយមានការង្វាស់ \\(6~\\text{dm}\\) ។ គណនាចម្ងាយផ្លូវធ្វើដំណើរពីកង់វិលបាន 140 ជុំ ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៨</h2><p>បរិមាត្រនៃកង់ (ប្រវែងធ្វើដំណើរក្នុង 1 ជុំ) ៖ \\[p = \\pi d\\] ដោយ \\(d = 6~\\text{dm}\\) និងយក \\(\\pi \\approx \\frac{22}{7}\\) គេបាន ៖ \\[p = \\frac{22}{7} \\times 6 = \\frac{132}{7}~\\text{dm}\\] ចម្ងាយផ្លូវធ្វើដំណើរពីកង់វិលបាន 140 ជុំ ៖ \\[\\begin{aligned}\n    S &amp;= 140 \\times p \\\\\n    &amp;= 140 \\times \\frac{132}{7} \\\\\n    &amp;= 20 \\times 132 \\\\\n    &amp;= 2640~\\text{dm} = 264~\\text{m}\n    \\end{aligned}\\] (បើគណនាតាម \\(\\pi \\approx 3.14\\) នោះ \\(S = 140 \\times 3.14 \\times 6 = 2637.6~\\text{dm} \\approx 263.76~\\text{m}\\)) ។</p><p>ដូចនេះ ចម្ងាយផ្លូវធ្វើដំណើរគឺ \\(264~\\text{m}\\) (ឬ \\(2640~\\text{dm}\\)) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៩</h2><p>តើកង់រថយន្តដែលមានកាំ \\(28~\\text{dm}\\) វិលបានប៉ុន្មានជុំ ពេលដែលវាធ្វើដំណើរបាន \\(1.1~\\text{km}\\) ? (យក \\(\\pi \\approx \\frac{22}{7}\\))</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៩</h2><p>បំលែងខ្នាតចម្ងាយផ្លូវ ៖ \\[1.1~\\text{km} = 1100~\\text{m} = 11000~\\text{dm}\\] បរិមាត្រនៃកង់រថយន្ត (ប្រវែង 1 ជុំ) ៖ \\[\\begin{aligned}\n    p &amp;= 2\\pi R \\\\\n    &amp;= 2 \\times \\frac{22}{7} \\times 28 \\\\\n    &amp;= 176~\\text{dm}\n    \\end{aligned}\\] ចំនួនជុំដែលកង់វិលបានគឺ ៖ \\[\\begin{aligned}\n    N &amp;= \\frac{S}{p} \\\\\n    &amp;= \\frac{11000}{176} \\\\\n    &amp;= 62.5~\\text{ជុំ}\n    \\end{aligned}\\] ដូចនេះ កង់រថយន្តវិលបាន \\(62.5~\\text{ជុំ}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១០</h2><p>គណនាបរិមាត្ររង្វង់និងផ្ទៃក្រឡាថាសរូបខាងក្រោម ។ \\(\\left(\\pi \\approx \\frac{22}{7}\\right)\\)</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១០ <span class=\"ts-pg\">(១/២)</span></h2><p>តាមរូបធរណីមាត្រដែលបានឱ្យ ៖</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>រង្វង់មានកាំ \\(r = 35~\\text{mm}\\) ៖ \\[\\begin{aligned}\n        p &amp;= 2\\pi r = 2 \\times \\frac{22}{7} \\times 35 = 220~\\text{mm} \\\\\n        \\mathcal{A} &amp;= \\pi r^2 = \\frac{22}{7} \\times 35^2 = 3850~\\text{mm}^2\n        \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>រង្វង់មានកាំ \\(r = 14~\\text{cm}\\) ៖ \\[\\begin{aligned}\n        p &amp;= 2\\pi r = 2 \\times \\frac{22}{7} \\times 14 = 88~\\text{cm} \\\\\n        \\mathcal{A} &amp;= \\pi r^2 = \\frac{22}{7} \\times 14^2 = 616~\\text{cm}^2\n        \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>រង្វង់មានអង្កត់ផ្ចិត \\(d = 77~\\text{mm} \\implies r = \\frac{77}{2} = 38.5~\\text{mm}\\) ៖ \\[\\begin{aligned}\n        p &amp;= \\pi d = \\frac{22}{7} \\times 77 = 242~\\text{mm} \\\\\n        \\mathcal{A} &amp;= \\pi r^2 = \\frac{22}{7} \\times (38.5)^2 = 4658.5~\\text{mm}^2\n        \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>រង្វង់មានអង្កត់ផ្ចិត \\(d = 14~\\text{cm} \\implies r = 7~\\text{cm}\\) ៖ \\[\\begin{aligned}\n        p &amp;= \\pi d = \\frac{22}{7} \\times 14 = 44~\\text{cm} \\\\\n        \\mathcal{A} &amp;= \\pi r^2 = \\frac{22}{7} \\times 7^2 = 154~\\text{cm}^2\n        \\end{aligned}\\]</div></li></ul><p>ដូចនេះ លទ្ធផលគឺ ៖</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១០ <span class=\"ts-pg\">(២/២)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(p = 220~\\text{mm}, \\mathcal{A} = 3850~\\text{mm}^2\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(p = 88~\\text{cm}, \\mathcal{A} = 616~\\text{cm}^2\\)</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>\\(p = 242~\\text{mm}, \\mathcal{A} = 4658.5~\\text{mm}^2\\)</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>\\(p = 44~\\text{cm}, \\mathcal{A} = 154~\\text{cm}^2\\) ។</div></li></ul>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១១</h2><p>ក្នុងរូបខាងស្តាំនេះ ចម្រៀកថាសពីរ \\(OAB\\) និង \\(OMN\\) ដែល \\(OA = OB = 12~\\text{cm}\\) ហើយ \\(AM = BN = 8~\\text{cm}\\) ។ គណនាផ្ទៃក្រឡាពណ៌ ។ (\\(\\pi \\approx 3.14\\))</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១១</h2><p>តាមរូបធរណីមាត្រ ផ្នែកពណ៌ជាចម្រៀកក្រវាត់ខណ្ឌដោយចម្រៀកថាសធំនិងចម្រៀកថាសតូច ដែលមានមុំផ្ចិត \\(\\alpha = 144^\\circ\\) ។</p><p>កាំក្នុង \\(r = 12~\\text{cm}\\) និងកាំក្រៅ \\(R = 12 + 8 = 20~\\text{cm}\\) ៖ \\[\\begin{aligned}\n    \\mathcal{A}_{\\text{ពណ៌}} &amp;= \\frac{\\alpha^\\circ}{360^\\circ} \\times \\pi (R^2 - r^2) \\\\\n    &amp;= \\frac{144}{360} \\times 3.14 \\times (20^2 - 12^2) \\\\\n    &amp;= 0.4 \\times 3.14 \\times (400 - 144) \\\\\n    &amp;= 0.4 \\times 3.14 \\times 256 \\\\\n    &amp;= 321.536~\\text{cm}^2 \\\\\n    &amp;\\approx 321.54~\\text{cm}^2\n    \\end{aligned}\\] (សម្គាល់ ៖ បើកាំក្រៅ \\(R = OA = 12~\\text{cm}\\) ហើយកាំក្នុង \\(r = OA - AM = 12 - 8 = 4~\\text{cm}\\) នោះផ្ទៃក្រឡាពណ៌គឺ \\(\\mathcal{A} = 0.4 \\times 3.14 \\times (12^2 - 4^2) = 160.768~\\text{cm}^2\\)) ។</p><p>ដូចនេះ ផ្ទៃក្រឡាពណ៌គឺ \\(\\mathcal{A} \\approx 321.54~\\text{cm}^2\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១២</h2><p>ផ្ទៃក្រឡាចម្រៀកថាសមានកាំប្រវែង \\(14~\\text{cm}\\) គឺ \\(123.2~\\text{cm}^2\\) ។ គណនាមុំផ្ចិតនៃចម្រៀកថាសនេះ ។ \\(\\left(\\pi \\approx \\frac{22}{7}\\right)\\)</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១២</h2><p>តាមរូបមន្តផ្ទៃក្រឡាចម្រៀកថាស ៖ \\[\\mathcal{A} = \\pi R^2 \\times \\frac{\\alpha^\\circ}{360^\\circ}\\] គេទាញបានមុំផ្ចិត \\(\\alpha^\\circ\\) ៖ \\[\\alpha^\\circ = \\frac{\\mathcal{A} \\times 360^\\circ}{\\pi R^2}\\] ដោយ \\(\\mathcal{A} = 123.2~\\text{cm}^2, R = 14~\\text{cm}\\) និងយក \\(\\pi \\approx \\frac{22}{7}\\) គេបាន ៖ \\[\\begin{aligned}\n    \\pi R^2 &amp;= \\frac{22}{7} \\times 14^2 = 22 \\times 28 = 616~\\text{cm}^2 \\\\\n    \\alpha^\\circ &amp;= \\frac{123.2 \\times 360^\\circ}{616} \\\\\n    &amp;= 0.2 \\times 360^\\circ \\\\\n    &amp;= 72^\\circ\n    \\end{aligned}\\] ដូចនេះ មុំផ្ចិតនៃចម្រៀកថាសគឺ \\(\\alpha = 72^\\circ\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១៣</h2><p>\\(OABC\\) ជាចម្រៀកថាសមានកាំប្រវែង \\(25~\\text{cm}\\) និងមុំផ្ចិតនៃចម្រៀកថាសនេះមានរង្វាស់ \\(90^\\circ\\) ។ គណនាបរិមាត្រនៃចម្រៀកថាស និងផ្ទៃក្រឡាពណ៌ ។ (\\(\\pi \\approx 3.14\\))</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១៣ <span class=\"ts-pg\">(១/២)</span></h2><p><b>1. គណនាបរិមាត្រនៃចម្រៀកថាស \\(OABC\\) ៖</b> ប្រវែងធ្នូ \\(\\arc{AC}\\) នៃចម្រៀកថាសមុំ \\(90^\\circ\\) ៖ \\[\\begin{aligned}\n    \\arc{AC} &amp;= 2\\pi R \\times \\frac{90^\\circ}{360^\\circ} \\\\\n    &amp;= 2 \\times 3.14 \\times 25 \\times \\frac{1}{4} \\\\\n    &amp;= 39.25~\\text{cm}\n    \\end{aligned}\\] បរិមាត្រនៃចម្រៀកថាសគឺ ៖ \\[\\begin{aligned}\n    p &amp;= \\arc{AC} + OA + OC \\\\\n    &amp;= 39.25 + 25 + 25 \\\\\n    &amp;= 89.25~\\text{cm}\n    \\end{aligned}\\]</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១៣ <span class=\"ts-pg\">(២/២)</span></h2><p><b>2. គណនាផ្ទៃក្រឡាពណ៌ (កំណាត់ថាស) ៖</b> ផ្ទៃក្រឡាពណ៌ស្មើនឹងផ្ទៃក្រឡាចម្រៀកថាស ដកផ្ទៃក្រឡាត្រីកោណកែង \\(OAC\\) ៖ \\[\\begin{aligned}\n    \\mathcal{A}_{\\text{ចម្រៀកថាស}} &amp;= \\pi R^2 \\times \\frac{90^\\circ}{360^\\circ} \\\\\n    &amp;= 3.14 \\times 25^2 \\times \\frac{1}{4} \\\\\n    &amp;= 3.14 \\times 625 \\times 0.25 \\\\\n    &amp;= 490.625~\\text{cm}^2\n    \\end{aligned}\\] ផ្ទៃក្រឡាត្រីកោណកែង \\(OAC\\) ៖ \\[\\begin{aligned}\n    \\mathcal{A}_{\\triangle OAC} &amp;= \\frac{1}{2} \\times OA \\times OC \\\\\n    &amp;= \\frac{1}{2} \\times 25 \\times 25 \\\\\n    &amp;= 312.5~\\text{cm}^2\n    \\end{aligned}\\] ផ្ទៃក្រឡាពណ៌ ៖ \\[\\begin{aligned}\n    \\mathcal{A}_{\\text{ពណ៌}} &amp;= \\mathcal{A}_{\\text{ចម្រៀកថាស}} - \\mathcal{A}_{\\triangle OAC} \\\\\n    &amp;= 490.625 - 312.5 \\\\\n    &amp;= 178.125~\\text{cm}^2\n    \\end{aligned}\\] ដូចនេះ បរិមាត្រចម្រៀកថាសគឺ \\(p = 89.25~\\text{cm}\\) និងផ្ទៃក្រឡាពណ៌គឺ \\(\\mathcal{A}_{\\text{ពណ៌}} = 178.125~\\text{cm}^2\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១៤</h2><p>ចំណុច \\(A, B, C\\) និង \\(D\\) ស្ថិតនៅលើរង្វង់ \\(O\\) កាំ \\(14~\\text{cm}\\) ។ រង្វង់មួយមានអង្កត់ផ្ចិត \\(AO\\) ហើយកាត់តាមចំណុច \\(A, P, O\\) និង \\(Q\\) ។ គណនាផ្ទៃក្រឡានៃផ្ទៃពណ៌ ។ \\(\\left(\\pi \\approx \\frac{22}{7}\\right)\\)</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១៤</h2><p>តាមរូបធរណីមាត្រ ផ្ទៃពណ៌គឺជាផ្ទៃនៃរង្វង់ធំផ្ចិត \\(O\\) ទាំងមូល ដកផ្ទៃនៃរង្វង់តូចដែលមានអង្កត់ផ្ចិត \\(AO\\) (កាត់តាម \\(A, P, O, Q\\)) ៖</p><p>កាំរង្វង់ធំគឺ \\(R = 14~\\text{cm}\\) ៖ \\[\\begin{aligned}\n    \\mathcal{A}_{\\text{ធំ}} &amp;= \\pi R^2 \\\\\n    &amp;= \\frac{22}{7} \\times 14^2 \\\\\n    &amp;= 22 \\times 28 \\\\\n    &amp;= 616~\\text{cm}^2\n    \\end{aligned}\\] អង្កត់ផ្ចិតរង្វង់តូចគឺ \\(d = AO = 14~\\text{cm} \\implies r = \\frac{14}{2} = 7~\\text{cm}\\) ៖ \\[\\begin{aligned}\n    \\mathcal{A}_{\\text{តូច}} &amp;= \\pi r^2 \\\\\n    &amp;= \\frac{22}{7} \\times 7^2 \\\\\n    &amp;= 22 \\times 7 \\\\\n    &amp;= 154~\\text{cm}^2\n    \\end{aligned}\\] ផ្ទៃក្រឡានៃផ្ទៃពណ៌គឺ ៖ \\[\\begin{aligned}\n    \\mathcal{A}_{\\text{ពណ៌}} &amp;= \\mathcal{A}_{\\text{ធំ}} - \\mathcal{A}_{\\text{តូច}} \\\\\n    &amp;= 616 - 154 \\\\\n    &amp;= 462~\\text{cm}^2\n    \\end{aligned}\\] ដូចនេះ ផ្ទៃក្រឡានៃផ្ទៃពណ៌គឺ \\(\\mathcal{A}_{\\text{ពណ៌}} = 462~\\text{cm}^2\\) ។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">មេរៀនទី ១៧</p><h1>ចប់មេរៀន</h1><p class=\"ts-sub\">រង្វង់</p>"}];
